(6658729, 995934, 142833, '<td valign="top">Cute photo, love the definition in the woman''s eyes.<br/> <br/>I like how the rat on the left is reaching out toward the woman.</td>', 'Cute photo, love the definition in the woman''s eyes. I like how the rat on the left is reaching out toward the woman.', '2012-01-30 09:45:05.000000', NULL, 1),
(6658731, 995801, 142833, '<td valign="top">Very nice, the photo works well with its title, which means it is telling the story it set out to tell. :)</td>', 'Very nice, the photo works well with its title, which means it is telling the story it set out to tell. :)', '2012-01-30 09:46:01.000000', NULL, 1),
