(6658792, 995832, 141319, '<td valign="top">Can''t wait to hear how you made this picture - very intriguing</td>', 'Can''t wait to hear how you made this picture - very intriguing', '2012-01-30 10:47:54.000000', NULL, 1),
(6658793, 995872, 141319, '<td valign="top">Great idea - I find some of the reflections too much (the board/crate thingy on top, the "hairline" below the camera, the catch for the leash) and "confusing" which is a pitty</td>', 'Great idea - I find some of the reflections too much (the board/crate thingy on top, the "hairline" below the camera, the catch for the leash) and "confusing" which is a pitty', '2012-01-30 10:51:08.000000', NULL, 1),
(6658794, 995967, 41129, '<td valign="top">I don''t even know where to start with this lol.. exposure is way off, theres no way those birds are his pets or interested in giving him any kind of affection.. sorry but epic fail lol</td>', 'I don''t even know where to start with this lol.. exposure is way off, theres no way those birds are his pets or interested in giving him any kind of affection.. sorry but epic fail lol', '2012-01-30 10:51:39.000000', NULL, 1),
(6658796, 995842, 94265, '<td valign="top">This is very nice. Great DOF, a sweet moment, the dog certainly looks adoring of his mistress! Could be a bit sharper on the pair but overall, lovely.</td>', 'This is very nice. Great DOF, a sweet moment, the dog certainly looks adoring of his mistress! Could be a bit sharper on the pair but overall, lovely.', '2012-01-30 10:52:15.000000', NULL, 1),
