INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6658974, 995355, 143086, '<td valign="top">Nice idea. A bit too much clipping though for my tastes. Perhaps a darker tint too</td>', 'Nice idea. A bit too much clipping though for my tastes. Perhaps a darker tint too', '2012-01-30 12:31:12.000000', NULL, 1),
(6658978, 995477, 143086, '<td valign="top">that is one adorable dog! The photo is fine technically, tho the model seems a bit stiff, and doesnt appear to be enjoying her rich surroundings. A softer touch on the pooch would help too</td>', 'that is one adorable dog! The photo is fine technically, tho the model seems a bit stiff, and doesnt appear to be enjoying her rich surroundings. A softer touch on the pooch would help too', '2012-01-30 12:33:21.000000', NULL, 1),
(6658986, 995686, 54446, '<td valign="top">Absolutely marking this way up in score.  (I''ll guess you''ll have to demonstrate compliance with rules.)  I think this is quite an accomplishment if you did it within the ruleset, rather than photoshop.  I assume you did it legally.  Great job!</td>', 'Absolutely marking this way up in score.  (I''ll guess you''ll have to demonstrate compliance with rules.)  I think this is quite an accomplishment if you did it within the ruleset, rather than photoshop.  I assume you did it legally.  Great job!', '2012-01-30 12:40:07.000000', NULL, 1),
(6658988, 995631, 143086, '<td valign="top">nice photo. The angle expresses the submissive relationship, and adulation from the dog. Nice bit of back lighting around the front of the snout. Dof is nice and the details are nice and rich. Conceptually, the symbolism of dark clouds and dark-faced man contrasts all of the good feelings I get. I''m suspicious of this seemingly happy relationship. I think this master has not been so nice, and the dog is waiting for a good opportunity to exact revenge.</td>', 'nice photo. The angle expresses the submissive relationship, and adulation from the dog. Nice bit of back lighting around the front of the snout. Dof is nice and the details are nice and rich. Conceptually, the symbolism of dark clouds and dark-faced man contrasts all of the good feelings I get. I''m suspicious of this seemingly happy relationship. I think this master has not been so nice, and the dog is waiting for a good opportunity to exact revenge.', '2012-01-30 12:41:41.000000', NULL, 1),
(6658989, 996012, 143086, '<td valign="top">Dont<br/> <br/>eat<br/> <br/>the pets</td>', 'Dont eat the pets', '2012-01-30 12:42:04.000000', NULL, 1),
