(6664353, 996034, 65234, '<td valign="top">Kind of a cross between a pet rock and Mr. Potato Head.  The pet, I mean.</td>', 'Kind of a cross between a pet rock and Mr. Potato Head.  The pet, I mean.', '2012-02-05 10:34:02.000000', NULL, 1),
(6664354, 995759, 65234, '<td valign="top">Looks like a tired dog who would just as soon stop for a drink and a nap, but soldiers on because he wants to stay with his human more than anything.  Very Lab-like :-)</td>', 'Looks like a tired dog who would just as soon stop for a drink and a nap, but soldiers on because he wants to stay with his human more than anything.  Very Lab-like :-)', '2012-02-05 10:35:02.000000', NULL, 1),
(6664355, 995353, 65234, '<td valign="top">Kids and dogs; a time-honored combination of cuteness!</td>', 'Kids and dogs; a time-honored combination of cuteness!', '2012-02-05 10:35:36.000000', NULL, 1),
(6664356, 995971, 65234, '<td valign="top">LOL!  The moving cat and servant clearly waiting to clean up breakfast after Their Majesties are done ... classic!!</td>', 'LOL!  The moving cat and servant clearly waiting to clean up breakfast after Their Majesties are done ... classic!!', '2012-02-05 10:37:33.000000', NULL, 1),
